import numpy as np
class Body:
 def __init__(self,x,z,w,h,m):
  self.p=np.array([x,z],float);self.v=np.zeros(2);self.a=0.;self.om=0.;self.w=w;self.h=h;self.m=m;self.im=1/m;self.ii=12/(m*(w*w+h*h))
 def verts(self):
  c=np.cos(self.a);s=np.sin(self.a);return np.array([[-self.w/2,-self.h/2],[self.w/2,-self.h/2],[self.w/2,self.h/2],[-self.w/2,self.h/2]])@np.array([[c,s],[-s,c]])+self.p

def cross(a,b):return a[0]*b[1]-a[1]*b[0]
def vel(b,r):return b.v+b.om*np.array([-r[1],r[0]])
def impulse(A,B,n,points,fr=.48):
 for p in points:
  ra=p-A.p
  rb=p-B.p if B else np.zeros(2)
  rv=(vel(B,rb) if B else np.zeros(2))-vel(A,ra)
  vn=rv@n
  if vn>=0:continue
  den=A.im+(B.im if B else 0)+cross(ra,n)**2*A.ii+(cross(rb,n)**2*B.ii if B else 0)
  j=-(1.07 if abs(vn)>15 else 1)*vn/den
  J=j*n;A.v-=J*A.im;A.om-=cross(ra,J)*A.ii
  if B:B.v+=J*B.im;B.om+=cross(rb,J)*B.ii
  t=np.array([-n[1],n[0]])
  rv=(vel(B,rb) if B else np.zeros(2))-vel(A,ra)
  den=A.im+(B.im if B else 0)+cross(ra,t)**2*A.ii+(cross(rb,t)**2*B.ii if B else 0)
  jt=np.clip(-(rv@t)/den,-j*fr,j*fr);J=jt*t
  A.v-=J*A.im;A.om-=cross(ra,J)*A.ii
  if B:B.v+=J*B.im;B.om+=cross(rb,J)*B.ii

def polyclip(poly,clip):
 for i in range(4):
  a=clip[i];b=clip[(i+1)%4];out=[]
  for j in range(len(poly)):
   p=poly[j];q=poly[(j+1)%len(poly)];dp=cross(b-a,p-a);dq=cross(b-a,q-a)
   if dp>=-1e-8:out.append(p)
   if (dp>=0)"'!=(dq>=0):out.append(p+(q-p)*dp/(dp-dq))
  poly=out
  if not poly:break
 return np.array(poly)
def collision(A,B):
 pa=A.verts();pb=B.verts();dep=1e9;best=None
 for a in [A.a,B.a]:
  for n in [np.array([np.cos(a),np.sin(a)]),np.array([-np.sin(a),np.cos(a)])]:
   va=pa@n;vb=pb@n;d=min(max(va),max(vb))-max(min(va),min(vb))
   if d<0:return
   if d<dep:dep=d;best=n
 if (B.p-A.p)@best<0:best=-best
 poly=polyclip(list(pa),pb)
 if len(poly)==0:return
 t=np.array([-best[1],best[0]])
 points=[poly[np.argmin(poly@t)],poly[np.argmax(poly@t)]]
 impulse(A,B,best,points)
 corr=max(dep-.015,0)*.6/(A.im+B.im)
 A.p-=best*corr*A.im;B.p+=best*corr*B.im

bs=[Body(0,18.75,12.2,37.5,12.2*37.5),Body(10.8,41.75,39.7,8.5,39.7*8.5),Body(27.25,72,6.8,52,6.8*52)]
states=[];dt=1/240
for k in range(1201):
 if k%60==0:states.append(np.array([[*b.p,b.a,*b.v,b.om] for b in bs]))
 for b in bs:
  b.v[1]-=200*dt;b.v*=.9998;b.om*=.9997;b.p+=b.v*dt;b.a+=b.om*dt
 for it in range(8):
  for b in bs:
   pts=b.verts();d=-min(pts[:,1])
   if d>0:
    ground=pts[pts[:,1]<.2].copy();ground[:,1]=0
    impulse(b,None,np.array([0.,-1.]),ground,.52)
    b.p[1]+=max(d-.005,0)*.5
  for i in range(3):
   for j in range(i+1,3):collision(bs[i],bs[j])
np.save('"'.tmp/states.npy',states)
for t,s in enumerate(states): print(round(t*.25,2),np.round(s[:,:3],2))
